effect.shader:
vec3 saturateCol(vec3 col, float sat) {
float grey = dot(col, vec3(0.2126, 0.7152, 0.0722));
return mix(vec3(grey), col, sat);
}
vec3 applyContrast(vec3 col, float con) {
return (col - 0.5) * con + 0.5;
}
float getLuma(vec3 col) {
return dot(col, vec3(0.2126, 0.7152, 0.0722));
}
vec3 rgb2hsv(vec3 c) {
vec4 K = vec4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);
vec4 p = mix(vec4(c.bg, K.wz), vec4(c.gb, K.xy), step(c.b, c.g));
vec4 q = mix(vec4(p.xyw, c.r), vec4(c.r, p.yzx), step(p.x, c.r));
float d = q.x - min(q.w, q.y);
float e = 1.0e-10;
return vec3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);
}
vec3 hsv2rgb(vec3 c) {
vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}
void main() {
vec2 uv = acScreenNorm;
vec4 src = texture2DCv(inputImg.texture, uv);
vec3 col = src.rgb;
float alpha = src.a;
vec3 invertCol = col;
if (invertMode == 0) {
invertCol = 1.0 - col;
}
else if (invertMode == 1) {
float luma = getLuma(col);
float invertLuma = 1.0 - luma;
invertCol = col * (invertLuma / max(luma, 0.001));
}
else if (invertMode == 2) {
vec3 hsv = rgb2hsv(col);
hsv.x = fract(hsv.x + 0.5);
invertCol = hsv2rgb(hsv);
}
else if (invertMode == 3) {
invertCol = vec3(1.0 - col.r, col.g, col.b);
}
else if (invertMode == 4) {
invertCol = vec3(col.r, 1.0 - col.g, col.b);
}
else if (invertMode == 5) {
invertCol = vec3(col.r, col.g, 1.0 - col.b);
}
else if (invertMode == 6) {
invertCol = vec3(1.0 - col.r, 1.0 - col.g, col.b);
}
else if (invertMode == 7) {
invertCol = vec3(1.0 - col.r, col.g, 1.0 - col.b);
}
else if (invertMode == 8) {
invertCol = vec3(col.r, 1.0 - col.g, 1.0 - col.b);
}
else if (invertMode == 9) {
vec3 inv = 1.0 - col;
float luma = getLuma(inv);
invertCol = vec3(luma);
}
else if (invertMode == 10) {
invertCol = pow(1.0 - col, vec3(0.7));
}
else if (invertMode == 11) {
float luma = getLuma(col);
float mask = 1.0 - smoothstep(0.0, threshold, luma);
invertCol = mix(col, 1.0 - col, mask);
}
else if (invertMode == 12) {
float luma = getLuma(col);
float mask = smoothstep(threshold, 1.0, luma);
invertCol = mix(col, 1.0 - col, mask);
}
else if (invertMode == 13) {
float luma = getLuma(col);
float lo = threshold * 0.5;
float hi = threshold + (1.0 - threshold) * 0.5;
float mask = smoothstep(lo, threshold, luma) * (1.0 - smoothstep(threshold, hi, luma));
invertCol = mix(col, 1.0 - col, mask);
}
else if (invertMode == 14) {
invertCol = vec3(1.0) - col * vec3(0.95, 0.85, 0.75);
invertCol = clamp(invertCol, 0.0, 1.0);
}
else if (invertMode == 15) {
float luma = getLuma(col);
float mask = step(threshold, luma);
invertCol = mix(col, 1.0 - col, mask);
}
vec3 result = mix(col, invertCol, amount);
result += brightness;
result = applyContrast(result, contrast);
result = saturateCol(result, saturation);
result = clamp(result, 0.0, 1.0);
gl_FragColor = vec4(result, alpha) * blend + (1.0 - blend) * src;
}
